sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float scatter;
uniform float grain;
layout(color) uniform half4 tint;
uniform float tintAmount;
uniform float brightness;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float2 hash22(float2 p) {
    return float2(hash21(p), hash21(p + float2(17.31, 5.17)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 jit = (hash22(floor(coord / max(grain, 1.0))) - 0.5) * scatter;
    float4 b = float4(blurred.eval(clamp(coord + jit, float2(0.0), size)));
    float3 rgb = mix(b.rgb, float3(tint.rgb) * b.a, tintAmount) + brightness * b.a;
    return fin(c, float4(max(rgb, float3(0.0)), b.a), opacity);
}
